// Native boundary ports model the audited TrainUnit -> cloneState sequence.
// Ownership adapter and framed ledger codec below are production code.
using System;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
namespace HarmonyLib{public class HarmonyMethod{public HarmonyMethod(MethodInfo m){}}public class Harmony{public List<string> Hooks=new();public void Patch(MethodInfo m,HarmonyMethod? p,HarmonyMethod? o,object? t,HarmonyMethod? f,object? il)=>Hooks.Add(m.DeclaringType!.Name+"."+m.Name);}}
namespace Il2CppSystem{public class Object{static long Next;public IntPtr Pointer{get;}=new(++Next);}}
public readonly struct WorldCoordinates{public int X{get;}public int Y{get;}public WorldCoordinates(int x,int y){X=x;Y=y;}}
public class UnitState:Il2CppSystem.Object{
 public uint id{get;set;}=4;public string type{get;set;}="dragonegg";public byte owner{get;set;}=2;public int health{get;set;}=70;
 public WorldCoordinates coordinates{get;set;}=new(0,0);public WorldCoordinates home{get;set;}=new(8,9);public bool moved{get;set;}=true;public bool attacked{get;set;}=true;
 public uint createdTurn{get;set;}=3;public byte xp{get;set;}=2;public byte kills{get;set;}=3;public UnitState? passengerUnit{get;set;}public object effects{get;set;}=new Il2CppSystem.Object();
 public void cloneState(UnitState old){id=old.id;home=old.home;moved=old.moved;attacked=old.attacked;xp=old.xp;kills=old.kills;passengerUnit=old.passengerUnit;effects=old.effects;NativeRogueUpgrade.AfterClone(this,old);}
}
public class TileData:Il2CppSystem.Object{public WorldCoordinates coordinates{get;set;}=new(0,0);public UnitState? unit{get;set;}public bool Accessible=true;}
public class MapData:Il2CppSystem.Object{public System.Collections.Generic.List<TileData> Tiles{get;set;}=new();}
public class GameState:Il2CppSystem.Object{public MapData Map{get;set;}=new();public byte CurrentPlayer{get;set;}=1;public uint CurrentTurn{get;set;}=8;public bool Admitted=true;public int Currency=25;}
public class PlayerState:Il2CppSystem.Object{public byte Id{get;set;}=1;}
public class UpgradeAction:Il2CppSystem.Object{public byte PlayerId{get;set;}=1;public string Type{get;set;}="babydragon";public WorldCoordinates Coordinates{get;set;}=new(0,0);public int Cost{get;set;}public void Execute(GameState s){}}
public static class MapDataExtensions{public static TileData? GetTile(MapData map,WorldCoordinates at)=>map.Tiles.SingleOrDefault(t=>t.coordinates.X==at.X&&t.coordinates.Y==at.Y);}
public static class ActionUtils{public static int SightWrites;public static void ExploreFromTile(GameState s,PlayerState p,TileData t,int range,bool queued){if(NativeRogueUpgrade.Discover(s,p,t)){SightWrites++;if(NativeRogueSight.Active is not null)NativeRogueSight.Active.Writes++;}}}
namespace Deception.PolyModAdapter{
 internal static class NativeRegroupSession{internal static List<string> Faults=new();internal static bool Ready(object state)=>((GameState)state).Admitted;internal static void Fault(string s)=>Faults.Add(s);}
 internal static class NativeGameStateEnvelope{internal static Dictionary<object,byte[]> Values=new();}
 internal static class NativeSpyNetwork{internal static bool Accessible(object state,object tile,byte actor)=>((TileData)tile).Accessible;}
 internal static class NativeRogueSight{
 internal sealed class Collection{internal int Writes;}
 internal static Collection? Active;internal static int Publications;
 sealed class Source:IDisposable{readonly Collection? Prior;internal Source(Collection collection){Prior=Active;Active=collection;}public void Dispose(){Active=Prior;}}
 internal static IDisposable ExchangeSource(object s,byte actor,object t,Collection c)=>new Source(c);
 internal static void CompleteCollection(object s,Collection c){Publications+=c.Writes;}
 }
 internal static class NativeRogueRules{
 internal static LedgerUnit? Row(object state,object unit){return NativeGameStateEnvelope.Values.TryGetValue(state,out var data)?NativeIdentityLedgerCodec.Decode(data,0).Units.SingleOrDefault(r=>r.NativeId==((UnitState)unit).id):null;}
 internal static bool CanCommand(object state,object unit,byte actor){var s=(GameState)state;var u=(UnitState)unit;var r=Row(s,u)?.Rogue;return s.CurrentPlayer==actor&&u.owner==actor&&(r==null||(r.Commander==actor&&r.AcquiredTurn==s.CurrentTurn));}
 internal static void SetOwner(object unit,byte owner){var u=(UnitState)unit;u.owner=owner;if(u.passengerUnit is UnitState p)p.owner=owner;}
 }
}
namespace Deception.Tests{
 public static class RogueUpgradeTests{
 static int Assertions;static List<string> Cases=new();static void Check(bool ok,string why){Assertions++;if(!ok)throw new Exception(why);}static void Test(string name,Action action){try{action();Cases.Add(name);}catch(Exception e){throw new Exception(name,e);}}
 sealed record Rig(GameState State,UnitState Unit,TileData Tile,UpgradeAction Action,byte[] Ledger);
 static Rig Start(bool rogue=true,bool active=false,bool mimic=false,bool cargo=false){NativeRogueUpgrade.Clear();NativeRegroupSession.Faults.Clear();NativeGameStateEnvelope.Values.Clear();ActionUtils.SightWrites=0;NativeRogueSight.Publications=0;NativeRogueSight.Active=null;var s=new GameState{CurrentPlayer=active?(byte)2:(byte)1};var u=new UnitState();if(cargo)u.passengerUnit=new(){id=5,type="warrior",health=60};var t=new TileData{unit=u};s.Map.Tiles.Add(t);var a=new UpgradeAction{PlayerId=s.CurrentPlayer};LedgerAppearance? appearance=mimic?new("warrior",new("Imperius","Default"),new("Imperius","Default"),new("Imperius","Default"),1,100,100,false,ApparentConcealment.Visible,-1,Array.Empty<string>()):null;var row=new LedgerUnit(2,4,true,mimic?LedgerActualKind.Mimic:LedgerActualKind.Genuine,mimic,appearance,PaidInvestmentKind.Known,7,Rogue:rogue?new(1,2,8):null);var ledger=new NativeIdentityLedger(Guid.NewGuid(),3,1,new[]{row},Array.Empty<LedgerReceipt>());byte[] bytes=NativeIdentityLedgerCodec.Encode(ledger,0);NativeGameStateEnvelope.Values[s]=bytes;return new(s,u,t,a,bytes);}
 static UnitState Replace(Rig r,bool clone=true){var replacement=new UnitState{id=99,type=r.Action.Type,owner=r.Action.PlayerId,health=120,moved=false,attacked=false,home=new(0,0)};r.Tile.unit=replacement;r.State.Currency-=r.Action.Cost;if(clone)replacement.cloneState(r.Unit);return replacement;}
 static string Facts(UnitState u)=>JsonSerializer.Serialize(new{u.id,u.type,u.health,u.moved,u.attacked,u.createdTurn,u.xp,u.kills,homeX=u.home.X,homeY=u.home.Y,effects=Native.Pointer(u.effects),cargo=u.passengerUnit is null?null:new{u.passengerUnit.id,u.passengerUnit.type,u.passengerUnit.health,u.passengerUnit.moved,u.passengerUnit.attacked}});
 public static int Run(){try{
 Test("hooks-use-safe-native-reference-abi",()=>{var h=new HarmonyLib.Harmony();NativeRogueUpgrade.Install(h);Check(h.Hooks.SequenceEqual(new[]{"UpgradeAction.Execute","UnitState.cloneState","ActionUtils.ExploreFromTile"}),"three exact boundaries");});
 foreach(string form in new[]{"babydragon","firedragon","larva","moth"})Test("remembered-growth-"+form,()=>{var r=Start();r.Action.Type=form;NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);Check(scope!=null,"Rogue boundary captured");var u=Replace(r);Check(u.owner==2&&u.type==form,"real native growth kept, commander restored immediately");string facts=Facts(u);ActionUtils.ExploreFromTile(r.State,new(){Id=1},r.Tile,2,true);ActionUtils.ExploreFromTile(r.State,new(){Id=2},r.Tile,2,true);Check(ActionUtils.SightWrites==0,"idle growth grants neither owner nor commander sight");Check(NativeRogueUpgrade.Finished(null,scope)==null,"success finalizer");Check(Facts(u)==facts&&r.State.Currency==25,"native growth health and flags untouched");Check(NativeGameStateEnvelope.Values[r.State].SequenceEqual(r.Ledger)&&NativeRegroupSession.Faults.Count==0,"ledger unchanged, no fault");});
 foreach(bool cargo in new[]{false,true})Test("commanded-paid-upgrade-"+cargo,()=>{var r=Start(active:true,cargo:cargo);r.Action.Cost=5;r.Action.Type="bomber";NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);var u=Replace(r);Check(u.owner==2&&(u.passengerUnit==null||u.passengerUnit.owner==2),"root and original cargo owner valid before other postfixes");Check(u.passengerUnit==r.Unit.passengerUnit&&u.effects==r.Unit.effects,"original cargo and effects references retained");string facts=Facts(u);ActionUtils.ExploreFromTile(r.State,new(){Id=2},r.Tile,1,true);ActionUtils.ExploreFromTile(r.State,new(){Id=1},r.Tile,1,true);Check(ActionUtils.SightWrites==1,"current commander discovery preserved exclusively");Check(NativeRogueUpgrade.Finished(null,scope)==null&&Facts(u)==facts&&r.State.Currency==20,"native cost, stats and flags retained");Check(NativeRogueSight.Publications==1&&NativeRogueSight.Active==null,"only accepted upgrade publishes commander footprint");});
 Test("expired-commander-upgrade-no-fog-refresh",()=>{var r=Start(active:true);r.State.CurrentTurn=9;NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);Replace(r);ActionUtils.ExploreFromTile(r.State,new(){Id=2},r.Tile,1,true);Check(ActionUtils.SightWrites==0,"expired authority cannot produce sight");Check(NativeRogueUpgrade.Finished(null,scope)==null&&r.Tile.unit!.owner==2,"ownership remains reserved");});
 Test("native-noop-keeps-original",()=>{var r=Start();NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);string facts=Facts(r.Unit);Check(NativeRogueUpgrade.Finished(null,scope)==null&&r.Tile.unit==r.Unit&&Facts(r.Unit)==facts,"no-op does not replace or reset body");});
 Test("native-failure-preserves-exception-and-cleans-scope",()=>{var r=Start();NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);var u=Replace(r);var error=new InvalidOperationException("native");Check(ReferenceEquals(NativeRogueUpgrade.Finished(error,scope),error)&&u.owner==2,"original exception and commander retained");Check(NativeRogueUpgrade.Discover(r.State,new PlayerState(),r.Tile),"scope removed after failure");});
 Test("unrelated-clone-is-not-reowned",()=>{var r=Start();NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);var other=new UnitState{owner=3};other.cloneState(new(){owner=1});Check(other.owner==3,"unrelated clone unaffected");NativeRogueUpgrade.Finished(null,scope);});
 Test("wrong-target-clone-is-not-reowned",()=>{var r=Start();NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);var u=Replace(r,false);u.type="warrior";u.cloneState(r.Unit);Check(u.owner==1,"wrong replacement not touched");Check(NativeRogueUpgrade.Finished(null,scope)!=null&&NativeRegroupSession.Faults.Count==1,"identity violation faults");});
 Test("different-arrival-is-never-reowned",()=>{var r=Start();NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);r.Tile.unit=new(){id=33,owner=3};Check(NativeRogueUpgrade.Finished(null,scope)!=null&&r.Tile.unit.owner==3,"foreign arrival unchanged");});
 Test("new-authority-is-never-overwritten",()=>{var r=Start();NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);var old=NativeIdentityLedgerCodec.Decode(r.Ledger,0);NativeGameStateEnvelope.Values[r.State]=NativeIdentityLedgerCodec.Encode(old with{Units=old.Units.Select(x=>x with{Rogue=new(1,3,8)}).ToArray()},0);r.Unit.owner=3;Check(NativeRogueUpgrade.Finished(null,scope)!=null&&r.Unit.owner==3,"new commander preserved");});
 Test("clear-invalidates-old-scope",()=>{var r=Start();NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);NativeRogueUpgrade.Clear();var u=Replace(r);Check(u.owner==1,"cleared callback inactive");Check(NativeRogueUpgrade.Finished(null,scope)==null&&u.owner==1,"retired session untouched");});
 Test("nested-scopes-restore-parent",()=>{var a=Start();NativeRogueUpgrade.BeforeUpgrade(a.Action,a.State,out var outer);var state=new GameState();var u=new UnitState{id=4};var t=new TileData{unit=u};state.Map.Tiles.Add(t);NativeGameStateEnvelope.Values[state]=a.Ledger;NativeRogueUpgrade.BeforeUpgrade(new UpgradeAction(),state,out var inner);Check(inner!=null&&!NativeRogueUpgrade.Discover(state,new PlayerState(),t),"inner active");Check(NativeRogueUpgrade.Discover(a.State,new PlayerState(),a.Tile),"outer hidden while nested");NativeRogueUpgrade.Finished(null,inner);Check(!NativeRogueUpgrade.Discover(a.State,new PlayerState(),a.Tile),"parent restored");NativeRogueUpgrade.Finished(null,outer);Check(NativeRogueUpgrade.Discover(a.State,new PlayerState(),a.Tile),"all scopes removed");});
 Test("covered-commanded-source-no-fog-refresh",()=>{var r=Start(active:true);r.Tile.Accessible=false;NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);Replace(r);ActionUtils.ExploreFromTile(r.State,new(){Id=2},r.Tile,1,true);Check(NativeRogueUpgrade.Finished(null,scope)==null&&ActionUtils.SightWrites==0&&NativeRogueSight.Publications==0,"covered source grants no upgrade discovery");});
 Test("failed-upgrade-does-not-publish-footprint",()=>{var r=Start(active:true);NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);Replace(r);ActionUtils.ExploreFromTile(r.State,new(){Id=2},r.Tile,1,true);var e=new Exception("native");Check(ReferenceEquals(NativeRogueUpgrade.Finished(e,scope),e)&&NativeRogueSight.Publications==0&&NativeRogueSight.Active==null,"failed native result does not retain sight receipt");});
 foreach(string mode in new[]{"ordinary","mimic","inactive","wrong-player","wrong-owner","dead","missing-tile"})Test("unrelated-native-path-"+mode,()=>{var r=Start(rogue:mode!="ordinary",mimic:mode=="mimic");if(mode=="inactive")r.State.Admitted=false;if(mode=="wrong-player")r.Action.PlayerId=3;if(mode=="wrong-owner")r.Unit.owner=3;if(mode=="dead")r.Unit.health=0;if(mode=="missing-tile")r.Action.Coordinates=new(8,8);NativeRogueUpgrade.BeforeUpgrade(r.Action,r.State,out var scope);Check(scope==null,"no Rogue scope");Check(NativeRogueUpgrade.Discover(r.State,new PlayerState(),r.Tile),"native discovery unchanged");});
 var result=new{tests=Cases.Count,assertions=Assertions,failed=0,names=Cases};Console.WriteLine(JsonSerializer.Serialize(result));return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}
